sect1.para:
基本解析（单文档）： yaml_parserparser("key:value\nlist:[1,2,3]");
autoroot=parser.parse();
if(auto*map=root->as_mapping()){
auto*val=map->get_member("key");
}

带错误处理的解析： yaml_parserparser(yaml_content);
autoresult=parser.try_parse();
if(result.has_value()){
//解析成功，使用result.value()
}else{
//解析失败
}

多文档解析： yaml_parserparser("---\ndoc1:value\n---\ndoc2:value\n");
autodocs=parser.parse_documents();
for(auto&doc:docs){
//处理每个文档
}
